<template>
  <div class="import-container q-pa-xl">
    <div class="row">
      <div style="width: 10%; margin: auto; padding-right: 5%">
        {{ $t('prompt') }}
      </div>
      <div style="width: 90%">
        <q-input
          outlined
          type="textarea"
          tabindex="0"
          :class="'full-width '"
          v-model="user_settings[setting_name]"
        >
        </q-input>
      </div>
    </div>

    <div class="row q-mt-sm">
      <div style="width: 10%; margin: auto; padding-right: 5%"></div>
      <div style="width: 90%">
        <q-btn
          color="primary"
          :label="$t('save')"
          @click="updateSetting(setting_name, user_settings[setting_name])"
        >
        </q-btn>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';

export default defineComponent({
  mixins: [helperMixin],

  data() {
    return {
      setting_name: CONSTANTS.AI_ASSISTANT_PROMPT,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;
    return {
      updateSetting,
      user_settings,
      loading_settings,
      loading: ref(false),
    };
  },
});
</script>
